const data = $input.item.json.valueRanges || [];

function sheetName(rangeName) {
  return String(rangeName || '').split('!')[0].replace(/^'/, '').replace(/'$/, '');
}

function parse(range) {
  if (!range?.values || range.values.length < 2) return [];
  const headers = range.values[0].map(h => String(h || '').trim());
  return range.values.slice(1)
    .filter(row => row.some(cell => String(cell || '').trim() !== ''))
    .map(row => Object.fromEntries(headers.map((h, i) => [h, row[i] || ''])));
}

const sheets = {};
for (const r of data) sheets[sheetName(r.range)] = parse(r);

function get(row, names) {
  const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
  const map = Object.fromEntries(Object.entries(row || {}).map(([k, v]) => [norm(k), v]));
  for (const name of names) {
    const v = map[norm(name)];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return '';
}

function amount(value) {
  const raw = String(value ?? '').trim()
    .replace(/[\s\u00A0\u202F]/g, '')
    .replace(/[^0-9,.-]/g, '');
  if (!raw) return 0;
  const comma = raw.lastIndexOf(',');
  const dot = raw.lastIndexOf('.');
  let normalized = raw;
  if (comma > dot) {
    normalized = raw.replace(/\./g, '').replace(',', '.');
  } else if (dot > comma && comma >= 0) {
    normalized = raw.replace(/,/g, '');
  } else if (comma >= 0) {
    normalized = raw.replace(',', '.');
  }
  const number = Number(normalized);
  return Number.isFinite(number) ? number : 0;
}

function money(n) {
  return '$' + Number(n || 0).toLocaleString('en-AU', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' AUD';
}

function status(v) {
  return String(v || '').trim().toUpperCase().replace(/\s+/g, '_');
}

function needsReview(row) {
  const v = String(get(row, ['Need Review', 'Need_Review']) || '').toLowerCase();
  return ['yes', 'true', '1', 'review'].includes(v);
}

const payments = sheets.Payments || [];
const contributions = sheets.Contributions || [];
const quotes = sheets.Quotes || [];
const timeline = sheets.Timeline || [];
const docs = sheets.Documents || [];

const paidPayments = payments.filter(r => ['PAID', 'AUTO_PAID', 'DEPOSIT_PAID', 'PARTIALLY_PAID'].includes(status(get(r, ['Status']))));
const pendingPayments = payments.filter(r => ['PENDING', 'DUE', 'OVERDUE', 'UNPAID', 'OPEN', 'AWAITING_PAYMENT', 'PARTIALLY_PAID'].includes(status(get(r, ['Status']))));
const reviewPayments = payments.filter(needsReview);
const openQuotes = quotes.filter(r => ['RECEIVED', 'UNDER_REVIEW', 'TO_REVIEW', 'PENDING'].includes(status(get(r, ['Status', 'Decision']))));

const totalPaid = paidPayments.reduce((s, r) => s + amount(get(r, ['Amount'])), 0);
const pendingAmount = pendingPayments.reduce((s, r) => s + amount(get(r, ['Amount'])), 0);
const totalContrib = contributions.reduce((s, r) => s + amount(get(r, ['Amount', 'Amount_AUD'])), 0);

let message = 'Weekly Summary - the project site\n\n';
message += 'Financials\n';
message += '- Total contributions: ' + money(totalContrib) + '\n';
message += '- Total paid in Payments: ' + money(totalPaid) + '\n';
message += '- Pending payment amount: ' + money(pendingAmount) + '\n';
message += '- Documents stored: ' + docs.length + '\n\n';

message += 'Attention\n';
message += '- Pending payments: ' + pendingPayments.length + '\n';
message += '- Need review: ' + reviewPayments.length + '\n';
message += '- Open quotes: ' + openQuotes.length + '\n\n';

message += 'Top pending payments\n';
if (!pendingPayments.length) {
  message += '- No pending payments found.\n';
} else {
  for (const r of pendingPayments.slice(0, 5)) {
    message += '- ' + (get(r, ['Description/Task']) || 'No description') + ' - ' + money(amount(get(r, ['Amount']))) + ' - ' + (get(r, ['Status']) || 'UNKNOWN') + '\n';
  }
}

message += '\nRecent timeline\n';
for (const r of timeline.filter(x => get(x, ['Description'])).slice(-5).reverse()) {
  message += '- ' + (get(r, ['Date']) || 'No date') + ' - ' + String(get(r, ['Description'])).slice(0, 120) + '\n';
}

message += '\nSuggested actions\n';
message += '- Review Payments rows marked Need Review.\n';
message += '- Confirm pending/overdue payments before the next weekly check.\n';
message += '- Keep document links attached to the relevant Payments rows.';

return [{ json: { message: String(message).slice(0, 3900) } }];
